# Generated by curate-skills
# Workflow: wordcount_mapreduce_histogram
# Function: visualize_histogram

"""Visualization phase of the wordcount MapReduce workflow.

Reads the combined word-frequency CSV produced by the reduce step (header
``word,count``) and renders a vertical bar histogram of the 20 most frequent
words (fewer bars when the corpus has fewer than 20 distinct words), writing it
as a PNG at 150 dpi. matplotlib's non-interactive Agg backend is selected
because the FaaSr container has no display server.
"""

import csv
import os
import tempfile

import matplotlib

matplotlib.use("Agg")  # headless container: no display server available

import matplotlib.pyplot as plt

TOP_N = 20


def visualize_histogram(folder: str, input1: str, output1: str) -> None:
    tmp_dir = tempfile.gettempdir()

    local_input = os.path.join(tmp_dir, "visualize_" + input1.rsplit("/", 1)[-1])
    faasr_get_file(local_file=local_input, remote_folder=folder, remote_file=input1)

    with open(local_input, "r", encoding="utf-8", newline="") as handle:
        raw = handle.read()

    if not raw.strip():
        message = (
            "visualize_histogram: word-frequency file %s in folder %s is empty"
            % (input1, folder)
        )
        faasr_log(message)
        raise ValueError(message)

    reader = csv.reader(raw.splitlines())
    rows = [row for row in reader if any(field.strip() for field in row)]

    header = [field.strip().lower() for field in rows[0]]
    if header[:2] != ["word", "count"]:
        message = (
            "visualize_histogram: %s in folder %s must start with the header "
            "'word,count', got %r" % (input1, folder, rows[0])
        )
        faasr_log(message)
        raise ValueError(message)

    counts = {}
    for line_number, row in enumerate(rows[1:], start=2):
        if len(row) < 2:
            message = (
                "visualize_histogram: line %d of %s has %d field(s), expected "
                "'word,count': %r" % (line_number, input1, len(row), row)
            )
            faasr_log(message)
            raise ValueError(message)

        word = row[0].strip()
        if not word:
            message = (
                "visualize_histogram: line %d of %s has an empty word field"
                % (line_number, input1)
            )
            faasr_log(message)
            raise ValueError(message)

        try:
            count = int(row[1].strip())
        except ValueError:
            message = (
                "visualize_histogram: count on line %d of %s is not an integer (%r)"
                % (line_number, input1, row[1])
            )
            faasr_log(message)
            raise ValueError(message)

        # Duplicate words would mean the reduce step did not fully merge; sum
        # them rather than silently dropping occurrences.
        counts[word] = counts.get(word, 0) + count

    if not counts:
        message = (
            "visualize_histogram: %s in folder %s contains a header but no word rows"
            % (input1, folder)
        )
        faasr_log(message)
        raise ValueError(message)

    total_occurrences = sum(counts.values())

    # Descending count, ties broken alphabetically (same order the reduce step uses).
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    top = ordered[:TOP_N]
    words = [word for word, _ in top]
    values = [count for _, count in top]

    faasr_log(
        "visualize_histogram: read %d distinct words / %d word occurrences from %s; "
        "plotting the top %d" % (len(counts), total_occurrences, input1, len(top))
    )

    figure, axes = plt.subplots(figsize=(10, 6))
    positions = range(len(words))
    axes.bar(positions, values, color="#3b76af", edgecolor="black", linewidth=0.5)
    axes.set_xticks(list(positions))
    axes.set_xticklabels(words, rotation=45, ha="right")
    axes.set_xlabel("Word")
    axes.set_ylabel("Occurrences")
    axes.set_title(
        "Top %d most frequent words (%d distinct words, %d total occurrences)"
        % (len(words), len(counts), total_occurrences)
    )
    axes.set_ylim(0, max(values) * 1.1 if max(values) > 0 else 1)
    axes.grid(axis="y", linestyle=":", alpha=0.5)
    axes.set_axisbelow(True)
    figure.tight_layout()

    local_output = os.path.join(tmp_dir, output1.rsplit("/", 1)[-1])
    figure.savefig(local_output, dpi=150, format="png")
    plt.close(figure)

    faasr_put_file(local_file=local_output, remote_folder=folder, remote_file=output1)
    faasr_log(
        "visualize_histogram: wrote %s (%d bars, %d dpi) to folder %s"
        % (output1, len(words), 150, folder)
    )
